import os
import sqlite3
import networkx as nx

from ErrorMapper import ErrorMapper
from typing import Dict, List, Tuple
from bs4 import BeautifulSoup
# 1. 升级后的扫描路径列表，完美适配你本地的 Dash DocSets 根目录
SCAN_DIRECTORIES = [
    # 你的专属本地绝对路径根目录（去掉了终端转义的反斜杠，保持 Python 路径规范）
    "/Users/wangdefu/Library/Application Support/Dash/DocSets",
    # 兜底路径：支持其他可能的自定义环境变量
    os.environ.get("DASH_DOCSETS_DIR", ""),
    os.path.expanduser("~/Library/Application Support/Dash/DocSets")
]

# 过滤空路径、去重并确保路径存在
SCAN_DIRECTORIES = list(set([d for d in SCAN_DIRECTORIES if d and os.path.exists(d)]))

# 2. 动态扫描并构建文档映射表
DOCSETS_CONFIG: Dict[str, str] = {}

print("🔍 正在自动遍历扫描 Dash 文档路径...")
for base_dir in SCAN_DIRECTORIES:
    try:
        # 支持多层级或单层级遍历，这里直接遍历根目录下的子文件夹
        for item in os.listdir(base_dir):
            item_path = os.path.join(base_dir, item)

            # 情况 A：如果子文件夹本身就是 .docset (例如 TypeScript.docset)
            if os.path.isdir(item_path) and item.endswith(".docset"):
                doc_name = item.replace(".docset", "").lower()
                db_path = os.path.join(item_path, "Contents", "Resources", "docSet.dsidx")
                if os.path.exists(db_path):
                    DOCSETS_CONFIG[doc_name] = item_path

            # 情况 B：如果是分类文件夹（如你的路径 /DocSets/TypeScript/ 这一层），再往深层扫一级
            elif os.path.isdir(item_path):
                try:
                    for sub_item in os.listdir(item_path):
                        sub_item_path = os.path.join(item_path, sub_item)
                        if os.path.isdir(sub_item_path) and sub_item.endswith(".docset"):
                            doc_name = sub_item.replace(".docset", "").lower()
                            db_path = os.path.join(sub_item_path, "Contents", "Resources", "docSet.dsidx")
                            if os.path.exists(db_path):
                                DOCSETS_CONFIG[doc_name] = sub_item_path
                except Exception:
                    continue

    except Exception as e:
        print(f"扫描目录 {base_dir} 时出错: {e}")

print(f"✅ 扫描完成！当前纳管的文档库: {list(DOCSETS_CONFIG.keys())}\n")

# 2. 定义 GraphML 文件的绝对路径（或相对路径）
GRAPHML_PATH = os.path.abspath("./node_with_attribute09.graphml")

# 3. 在启动时安全地加载图数据
if os.path.exists(GRAPHML_PATH):
    print(f"[*] 正在从 {GRAPHML_PATH} 加载图数据...", flush=True)
    try:
        # 使用 networkx 读取 graphml
        G = nx.read_graphml(GRAPHML_PATH)
        MAPPER = ErrorMapper(G)
        print(f"[+] 图数据加载成功！当前节点数: {G.number_of_nodes()}, 边数: {G.number_of_edges()}", flush=True)
    except Exception as e:
        print(f"[-] 读取 GraphML 文件失败: {str(e)}。初始化为空无向图。", flush=True)
        G = nx.Graph()
        MAPPER = ErrorMapper(G)
else:
    print(f"[!] 未找到 GraphML 文件: {GRAPHML_PATH}。初始化为空无向图。", flush=True)
    G = nx.Graph()
    MAPPER = ErrorMapper(G)

def map_error_to_context(log_file_name: str) -> str:
    global MAPPER

    with open(log_file_name, "r", encoding="utf-8") as f:
        stack_info = f.read()

    print(stack_info, flush=True)
    parsed_points = MAPPER.parse_arkts_hybrid_stack(stack_info)
    stack_log = ""
    for pt in parsed_points:
        stack_log += f'Traceback:\n File {pt['file_path']}, line {pt['line']}'
    matched_node = MAPPER.map_error_to_context(stack_log)
    return f"具体卡顿堆栈：{stack_info} \n🎯 成功映射报错点！定位到节点: [{matched_node.get('kind')}] {matched_node.get('name')}"


def _get_docset_paths(docset_dir: str) -> Tuple[str, str]:
    """辅助函数：获取单个 docset 的 DB 路径和 Documents 目录"""
    db_path = os.path.join(docset_dir, "Contents", "Resources", "docSet.dsidx")
    docs_dir = os.path.join(docset_dir, "Contents", "Resources", "Documents")
    return db_path, docs_dir

def search_dash_doc(keyword: str, docset_name: str = "all", limit: int = 5) -> str:
    """
    在多个或指定的 Dash 文档索引中搜索类、函数或方法。

    Args:
        keyword: 要搜索的 API 名称或关键字（如 'connect' 或 'DataFrame'）
        docset_name: 指定在哪个文档里找，可选值: 'all' 或配置的键名（如 'python', 'pandas'）
        limit: 每个文档库返回的最大结果条数
    """
    # 筛选要查询的文档库
    targets = {}
    if docset_name == "all":
        targets = DOCSETS_CONFIG
    elif docset_name in DOCSETS_CONFIG:
        targets = {docset_name: DOCSETS_CONFIG[docset_name]}
    else:
        return f"错误: 未知的文档库名称 '{docset_name}'。当前支持: {list(DOCSETS_CONFIG.keys())}"

    global_results = ["📊 搜索结果如下：\n"]
    found_any = False

    for name, path in targets.items():
        db_path, docs_dir = _get_docset_paths(path)
        if not os.path.exists(db_path):
            global_results.append(f"⚠️ 文档库 [{name}] 路径配置错误，已跳过。")
            continue

        try:
            conn = sqlite3.connect(db_path)
            cursor = conn.cursor()
            query = "SELECT name, type, path FROM searchIndex WHERE name LIKE ? LIMIT ?"
            cursor.execute(query, (f"%{keyword}%", limit))
            rows = cursor.fetchall()
            conn.close()

            if rows:
                found_any = True
                global_results.append(f"📂 **来自文档库: {name.upper()}**")
                for item_name, type_, rel_path in rows:
                    # 去掉 HTML 锚点获取真实文件物理路径
                    clean_path = rel_path.split('#')[0]
                    full_path = os.path.join(docs_dir, clean_path)

                    global_results.append(f"  - **名称**: {item_name} ({type_})")
                    global_results.append(f"    - **相对路径/锚点**: {rel_path}")
                    global_results.append(f"    - **本地文件路径**: {full_path}")
                global_results.append("")  # 换行隔离

        except Exception as e:
            global_results.append(f"❌ 读取文档库 [{name}] 出错: {str(e)}")

    if not found_any:
        return f"未在任何文档库中找到与 '{keyword}' 相关的索引。"

    return "\n".join(global_results)


def read_dash_file(file_path: str) -> str:
    """
    根据 search_dash_doc 返回的 '本地文件路径'，读取并提取该文档的纯文本内容。

    Args:
        file_path: 本地 HTML 文档的绝对路径
    """
    if not os.path.exists(file_path):
        return f"错误: 找不到文件 {file_path}"

    try:
        with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
            html_content = f.read()

        soup = BeautifulSoup(html_content, "html.parser")
        for script_or_style in soup(["script", "style", "meta", "noscript"]):
            script_or_style.decompose()

        text = soup.get_text(separator="\n")
        lines = (line.strip() for line in text.splitlines())
        chunks = (phrase.strip() for line in lines for phrase in line.split("  "))
        clean_text = "\n".join(chunk for chunk in chunks if chunk)

        return f"📖 文件内容预览 (来自 {file_path}):\n\n{clean_text[:8000]}"

    except Exception as e:
        return f"读取文件出错: {str(e)}"

